installers.install:
arch="$(uname -m)"
case "$arch" in
  x86_64) plat=linux-x64 sha=24972e3bc859fab2b46ed4c1e51f7d6130f06d3bd550811a114640de3370d0de ;;
  aarch64) plat=linux-arm64 sha=f1f6e96e0d8342b9dbf41d7e88255397a6a52ce3d8736ad6a4c6b59c9b62fefa ;;
  *) echo "unsupported arch: $arch" >&2; exit 1 ;;
esac
trap 'rm -f /tmp/claude' EXIT
curl -o /tmp/claude "https://downloads.claude.ai/claude-code-releases/2.1.296/$plat/claude"
echo "$sha  /tmp/claude" | sha256sum -c - >/dev/null
install -D -m 0755 /tmp/claude /usr/local/bin/claude

